package dev.voyage.workbench;
import com.getcapacitor.*;import com.getcapacitor.annotation.*;import android.app.Activity;import android.content.*;import androidx.activity.result.ActivityResult;import org.json.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;
@CapacitorPlugin(name="Workbench")
public final class WorkbenchPlugin extends Plugin {
 Host host;final ExecutorService executor=Executors.newSingleThreadExecutor();
 public void load(){executor.execute(()->{try{host=new Host(getContext());try{host.ensureIdle();host.store.recover();}catch(Exception active){}}catch(Exception e){android.util.Log.e("Voyage","Host initialization failed",e);}});}
 @PluginMethod public void request(PluginCall call){String method=call.getString("method");JSObject p=call.getObject("payload",new JSObject());
 if("copyText".equals(method)){getActivity().runOnUiThread(()->{try{if(!(p.opt("text") instanceof String))throw new Exception("Clipboard text must be a string.");ClipData clip=ClipData.newPlainText("Voyage draft",p.getString("text"));if(android.os.Build.VERSION.SDK_INT>=33){android.os.PersistableBundle extras=new android.os.PersistableBundle();extras.putBoolean(ClipDescription.EXTRA_IS_SENSITIVE,true);clip.getDescription().setExtras(extras);}ClipboardManager manager=(ClipboardManager)getContext().getSystemService(Context.CLIPBOARD_SERVICE);if(manager==null)throw new Exception("Clipboard is unavailable");manager.setPrimaryClip(clip);resolve(call,new JSONObject().put("copied",true));}catch(Exception error){call.reject(error.getMessage());}});return;}
 if("appearance".equals(method)){getActivity().runOnUiThread(()->{boolean dark=p.optBoolean("dark");android.view.Window w=getActivity().getWindow();w.getDecorView().setBackgroundColor(android.graphics.Color.parseColor(dark?"#17191c":"#f5f6f3"));w.setStatusBarColor(android.graphics.Color.parseColor(dark?"#17191c":"#f5f6f3"));w.setNavigationBarColor(android.graphics.Color.parseColor(dark?"#17191c":"#f5f6f3"));android.view.WindowInsetsController controller=w.getInsetsController();if(controller!=null)controller.setSystemBarsAppearance(dark?0:android.view.WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|android.view.WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS,android.view.WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|android.view.WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS);try{resolve(call,new JSONObject());}catch(Exception e){call.reject(e.getMessage());}});return;}
 if("runtimeInstallApproval".equals(method)){getActivity().runOnUiThread(()->{try{Intent approval=RuntimePacks.pendingApproval;if(approval==null)throw new Exception("The installation prompt is no longer available. Cancel the pending installation, then retry.");getActivity().startActivity(new Intent(approval));resolve(call,new JSONObject().put("opened",true));}catch(Exception error){call.reject(error.getMessage());}});return;}
 if("runtimeInstallPermission".equals(method)){getActivity().runOnUiThread(()->{try{getActivity().startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,android.net.Uri.parse("package:"+getContext().getPackageName())));resolve(call,new JSONObject().put("opened",true));}catch(Exception error){call.reject(error.getMessage());}});return;}
 if("pickImport".equals(method)){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(call,i,"importResult");return;}
 if("exportImage".equals(method)||"exportMedia".equals(method)||"export".equals(method)){executor.execute(()->{try{JSONObject prepared=PendingExport.prepareCall(getContext(),call);Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(prepared.getString("mime")).addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,prepared.getString("name"));getActivity().runOnUiThread(()->{try{startActivityForResult(call,intent,"exportResult");}catch(Exception error){PendingExport.discard(getContext(),prepared);call.reject(error.getMessage());}});}catch(Exception error){call.reject(error.getMessage());}});return;}
 if("openExternal".equals(method)){try{android.net.Uri uri=android.net.Uri.parse(p.getString("url"));if(!"https".equals(uri.getScheme()))throw new Exception("Secure links only");getActivity().startActivity(new Intent(Intent.ACTION_VIEW,uri));resolve(call,new JSONObject());}catch(Exception e){call.reject(e.getMessage());}return;}
 executor.execute(()->{try{if(host==null)throw new Exception("Native host failed to initialize");resolve(call,host.request(method,p));}catch(Exception e){call.reject(e.getMessage());}});
 }
 void resolve(PluginCall call,Object result)throws Exception{JSObject out=new JSObject();out.put("result",result==null?JSONObject.NULL:result);call.resolve(out);}
 @ActivityCallback private void importResult(PluginCall call,ActivityResult result){if(call==null)return;executor.execute(()->{try{if(result.getResultCode()!=Activity.RESULT_OK){resolve(call,null);return;}android.net.Uri uri=result.getData().getData();String name="Imported world.json";try(android.database.Cursor c=getContext().getContentResolver().query(uri,null,null,null,null)){if(c!=null&&c.moveToFirst()){int index=c.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME);if(index>=0)name=c.getString(index);}}try(java.io.InputStream input=getContext().getContentResolver().openInputStream(uri)){resolve(call,new JSONObject().put("name",name).put("source",new String(input.readAllBytes(),StandardCharsets.UTF_8)));}}catch(Exception e){call.reject(e.getMessage());}});}
 @ActivityCallback private void exportResult(PluginCall call,ActivityResult result){if(call==null)return;executor.execute(()->{try{JSONObject payload=call.getObject("payload");boolean saved=result.getResultCode()==Activity.RESULT_OK;if(saved){PendingExport.file(getContext(),payload);if(result.getData()==null||result.getData().getData()==null)throw new Exception("No export destination returned");try(java.io.OutputStream out=getContext().getContentResolver().openOutputStream(result.getData().getData(),"wt")){PendingExport.write(getContext(),payload,out);}}resolve(call,new JSONObject().put("saved",saved));}catch(Exception e){call.reject(e.getMessage());}finally{PendingExport.discard(getContext(),call.getObject("payload"));}});}
}
